using System;using System.Drawing;using System.IO;
namespace MEHR_PACSViewer.Properties
{
 internal static class Resources
 {
  private static Image Load(string s){byte[] b=Convert.FromBase64String(s);using(MemoryStream m=new MemoryStream(b))return Image.FromStream(m);}
  private static Image _blue,_light,_red;
  internal static Image Blue{get{if(_blue==null)_blue=Load("");return _blue;}}
  internal static Image LightBlue{get{if(_light==null)_light=Load("");return _light;}}
  internal static Image RedMicrophone{get{if(_red==null)_red=Load("");return _red;}}
 }
}